arguments.command:
python3 - <<'EOF'
p='src/storage/worktree.ts'
s=open(p).read()
s=s.replace(''' * Restore a snapshot into the checkout at `cwd`, which must be clean (no changes, no untracked files): put HEAD on the snapshot's branch (recreate a
 * local-only branch,''',''' * Restore a snapshot into the checkout at `cwd`, which must be clean (see `isCheckoutClean`): put HEAD on the
 * snapshot's branch (recreate a local-only branch,''')
s=s.replace('''/** What tells two states apart''','''/** No changes and no untracked files (ignored files aside): a failed restore can then simply clean up. */
export async function isCheckoutClean(cwd: string): Promise<boolean> {
	return (await git(cwd, ["status", "--porcelain"])).trim() === "";
}

/** What tells two states apart''')
open(p,'w').write(s)
p='src/worktree.ts'
s=open(p).read()
a='''			const before = await captureState(cwd, limits);
			if (
				before.indexTree !== before.headTree ||
				before.worktreeTree !== before.headTree
			) {
				log.warning(
					`The checkout has uncommitted changes; not restoring ${short(target.stash)}`,
				);
				this.lastKey = stateKey(before);
				return `[pi-action] The checkout already had uncommitted changes when this run started,'''
assert a in s
s=s.replace(a,'''			if (!(await isCheckoutClean(cwd))) {
				log.warning(
					`The checkout has uncommitted changes or untracked files; not restoring ${short(target.stash)}`,
				);
				this.lastKey = stateKey(await captureState(cwd, limits));
				return `[pi-action] The checkout already had uncommitted changes or untracked files when this run started,''')
s=s.replace('\tisClean,\n','\tisCheckoutClean,\n\tisClean,\n')
open(p,'w').write(s)
EOF
sed -n '/starts clean when the restore fails/,/^\t});/p' src/storage/worktree.test.ts
